
.setup {
  width: 100%;
  max-width: 720px;
  margin: 0 auto;
  padding: 12px;
  background: var(--c-bg);
  border: 1px solid var(--c-border);
  color: var(--c-text);
  font-family: var(--font-sans);
  font-size: 13px;
  line-height: 1.5;
}

.setup-head {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--c-border);
}

.brand {
  font-family: var(--font-mono);
  font-weight: 700;
  letter-spacing: 0.16em;
  color: var(--c-primary);
}

.subtitle {
  font-size: 12px;
  color: var(--c-text-muted);
}

.hint {
  margin: 8px 0 4px;
  font-size: 12px;
  color: var(--c-text-muted);
}

.field {
  margin-top: 10px;
}

.field-label {
  margin-bottom: 5px;
  font-size: 11px;
  letter-spacing: 0.08em;
  color: var(--c-text-muted);
}

.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.chip {
  padding: 3px 10px;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  color: var(--c-text);
  font-family: inherit;
  font-size: 12px;
  cursor: pointer;
}

.chip.picked {
  border-color: var(--c-primary);
  color: var(--c-primary);
  box-shadow: inset 0 0 0 1px var(--c-primary);
}

.input {
  width: 100%;
  margin-top: 6px;
  padding: 5px 8px;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  color: var(--c-text);
  font-family: inherit;
  font-size: 12px;
}

.input:focus {
  outline: none;
  border-color: var(--c-primary);
}

.submit {
  width: 100%;
  margin-top: 14px;
  padding: 8px;
  background: var(--c-primary);
  border: none;
  color: var(--c-bg);
  font-family: inherit;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.08em;
  cursor: pointer;
}

.submit:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.warn {
  margin-top: 6px;
  font-size: 12px;
  color: var(--c-warning);
}
